    "accuse sb of sth": {"zh":"指控/指责某人……","sentence":"Critics accused the government of ignoring rural schools.","sentenceZh":"批评者指责政府忽视农村学校。","tip":"accuse sb of sth，介词 of 不可换 for；近义 charge sb with sth。","blankStart":8,"blankEnd":15,"wordId":72,"word":"accuse","pos":"v.","phonetic":"[aˈkju:z]"},
