    "acknowledge sth as/to be": {"zh":"承认……是","sentence":"The institute acknowledged the method as the standard for such tests.","sentenceZh":"该机构承认这一方法是此类检测的标准。","tip":"acknowledge A as B 结构；亦可用 acknowledge that 从句。","blankStart":14,"blankEnd":40,"wordId":80,"word":"acknowledge","pos":"v.","phonetic":"[akˈnɑ:lɪd3]"},
