    "act like a grown-up": {"zh":"表现得像个大人","sentence":"Someone in the room had to act like a grown-up and apologise.","sentenceZh":"屋里总得有人像个大人一样道歉。","tip":"口语表达，含责备语气。","blankStart":27,"blankEnd":46,"wordId":2944,"word":"grown-up","pos":"adj. / n.","phonetic":"[ˌɡrəʊn ˈʌp]"},
