    "address an audience": {"zh":"向听众讲话","sentence":"She addressed an audience of several thousand without a single note.","sentenceZh":"她面对数千名听众演讲，一张讲稿也没带。","tip":"address 作动词除「地址」外的熟词僻义：演讲、处理（address the issue）、称呼；写作中 address a problem 比 solve 更书面。","blankStart":4,"blankEnd":25,"wordId":111,"word":"address","pos":"n. / v.","phonetic":"[aˈdres]"},
    "adequate preparation": {"zh":"充分的准备","sentence":"No amount of talent can compensate for inadequate preparation.","sentenceZh":"再高的天赋也弥补不了准备不足。","tip":"adequate 前常加 insufficient、inadequate、proper 等程度词，是阅读中判断作者态度的信号词。","blankStart":41,"blankEnd":61,"wordId":113,"word":"adequate","pos":"adj.","phonetic":"[ˈædɪkwat]"},
    "adhere to sth": {"zh":"坚持；遵守；黏附于……","sentence":"Member states are expected to adhere to the treaty even when it conflicts with domestic law.","sentenceZh":"成员国即使在本国法律与之冲突时也应遵守该条约。","tip":"to 为介词，后接名词/动名词；近义 stick to、comply with、abide by；adhere 本义「黏附」引申为「坚守」。常考 adhere to principles/rules。","blankStart":30,"blankEnd":39,"wordId":114,"word":"adhere","pos":"v.","phonetic":"[adˈhɪr]"},
    "adherents of a religion": {"zh":"某宗教的信徒","sentence":"Adherents of the religion have preserved the ritual largely unchanged for centuries.","sentenceZh":"该宗教的信徒数百年来基本原封不动地保留着这一仪式。","tip":"adherent 指政党、学说的拥护者，比 supporter 更书面；adherent to a theory 表示「坚持某理论的人」。","blankStart":0,"blankEnd":25,"wordId":116,"word":"adherent","pos":"n. / adj.","phonetic":"[adˈhɪrant]"},
    "administer a drug to sb": {"zh":"给某人用药","sentence":"The nurse administered the drug to the patient at four-hour intervals.","sentenceZh":"护士每隔四小时给病人用一次药。","tip":"结构为 administer sth to sb，不可写成 administer sb sth；名词 administration 兼指「给药」与「管理」。","blankStart":10,"blankEnd":34,"wordId":121,"word":"administer","pos":"v.","phonetic":"[adˈmɪnɪstar]"},
    "administer justice": {"zh":"执法；司法","sentence":"A legal system that administers justice slowly may be little better than none at all.","sentenceZh":"司法效率低下的法律体系未必好过没有法律。","tip":"administer 三义：管理（administer a company）、执行（administer justice/laws）、给予（administer a drug）；注意与 administrative（行政的）词形区分。","blankStart":20,"blankEnd":39,"wordId":121,"word":"administer","pos":"v.","phonetic":"[adˈmɪnɪstar]"},
    "admirable courage": {"zh":"令人钦佩的勇气","sentence":"Her admirable courage in admitting the error won her more respect than the error cost her.","sentenceZh":"她承认错误时令人钦佩的勇气为她赢得的尊重，远超过错误造成的损失。","tip":"admirable 表「值得赞赏的」，用于褒义；admir able 与 admiring（羡慕的）易混：admiring glances 是艳羡的目光。","blankStart":4,"blankEnd":21,"wordId":123,"word":"admirable","pos":"adj.","phonetic":"[ˈædmərəb(ə)l]"},
    "admire sb for sth": {"zh":"因……钦佩某人","sentence":"Colleagues admired him for refusing to take credit that belonged to others.","sentenceZh":"同事们钦佩他拒绝把属于别人的功劳据为己有。","tip":"admire sb for sth 是固定结构；被动式 be admired for；写作中可替换 respect sb for。","blankStart":11,"blankEnd":18,"wordId":124,"word":"admire","pos":"v.","phonetic":"[ədˈmaɪər]"},
    "admiring glances": {"zh":"羡慕的目光","sentence":"The young engineer drew admiring glances from every corner of the room.","sentenceZh":"这位年轻工程师引来满场羡慕的目光。","tip":"-ing 形容词表主动（令人羡慕的），-ed 形容词表被动（admired 被钦佩的），是形容词分词辨析的典型考点。","blankStart":24,"blankEnd":40,"wordId":126,"word":"admiring","pos":"adj. / v.","phonetic":"[ədˈmaɪərɪŋ]"},
